 "content": "def transform(grid):
    """Mirror each colored tile into its adjacent partner across a vertical divider."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Divider color: the nonzero value spanning complete rows and columns.
    divider = None
    for v in set(x for row in g for x in row if x):
        if any(all(x == v for x in row) for row in g) and any(all(g[r][c] == v for r in range(h)) for c in range(w)):
            divider = v
            break
    if divider is None:
        return g
    hr = [r for r in range(h) if all(x == divider for x in g[r])]
    vc = [c for c in range(w) if all(g[r][c] == divider for r in range(h))]
    rb = [-1] + hr + [h]
    cb = [-1] + vc + [w]
    rows = [(rb[i]+1, rb[i+1]) for i in range(len(rb)-1)]
    cols = [(cb[i]+1, cb[i+1]) for i in range(len(cb)-1)]

    def cells(rng, crng):
        r0, r1 = rng; c0, c1 = crng
        return {(r-r0, c-c0): g[r][c]
                for r in range(r0, r1) for c in range(c0, c1)
                if g[r][c] not in (0, divider)}

    for band in rows:
        objects = [cells(band, col) for col in cols]
        occupied = [bool(obj) for obj in objects]
        # For each occupied panel, partner it with an adjacent panel. A populated
        # neighbor takes precedence; otherwise the empty neighbor toward the center.
        pairs = []
        for i, has in enumerate(occupied):
            if not has:
                continue
            if i + 1 < len(cols) and occupied[i+1]:
                pairs.append((i, i+1))
            elif i > 0 and occupied[i-1]:
                pairs.append((i-1, i))
            elif i == 0 and len(cols) > 1:
                pairs.append((i, i+1))
            elif i == len(cols)-1 and i > 0:
                pairs.append((i-1, i))
            elif i < len(cols)//2 and i+1 < len(cols):
                pairs.append((i, i+1))
            elif i > 0:
                pairs.append((i-1, i))
        # Deduplicate and process each pair once, taking the left tile as source
        # whenever present, otherwise reflecting the right tile into the left.
        for left, right in sorted(set(pairs)):
            src = objects[left] if objects[left] else objects[right]
            if not src:
                continue
            # Preserve the divider/background and replace only the destination tile.
            dest_i = right if objects[left] else left
            dr0, dr1 = band
            dc0, dc1 = cols[dest_i]
            for rr in range(dr0, dr1):
                for cc in range(dc0, dc1):
                    if g[rr][cc] not in (0, divider):
                        g[rr][cc] = 0
            src_col = cols[left] if objects[left] else cols[right]
            sr0, sr1 = band; sc0, sc1 = src_col
            for (lr, lc), value in src.items():
                target_c = dc0 + (sc1 - sc0 - 1 - lc)
                if 0 <= target_c < dc1:
                    g[dr0 + lr][target_c] = value
    return g
